def shlex_split(s):
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        # Skip whitespace
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            break

        # Start a new token
        token = []
        has_content = False

        while i < n:
            c = s[i]

            if c.isspace():
                # End of token
                break

            if c == "'":
                # Single quote: everything literal until closing single quote
                i += 1
                while i < n and s[i] != "'":
                    token.append(s[i])
                    i += 1
                # Skip the closing quote
                if i < n:
                    i += 1
                has_content = True

            elif c == '"':
                # Double quote: backslash escapes only " or \
                i += 1
                while i < n and s[i] != '"':
                    if s[i] == '\\':
                        # Check what follows the backslash
                        if i + 1 < n and s[i + 1] in ('"', '\\'):
                            token.append(s[i + 1])
                            i += 2
                        else:
                            # Backslash is literal
                            token.append('\\')
                            i += 1
                    else:
                        token.append(s[i])
                        i += 1
                # Skip the closing quote
                if i < n:
                    i += 1
                has_content = True

            elif c == '\\':
                # Backslash outside quotes: escape next character
                if i + 1 < n:
                    token.append(s[i + 1])
                    i += 2
                else:
                    # Trailing backslash, treat as literal
                    token.append('\\')
                    i += 1
                has_content = True

            else:
                # Regular character
                token.append(c)
                i += 1
                has_content = True

        if has_content:
            tokens.append(''.join(token))

    return tokens
