def shlex_split(s):
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        # Skip whitespace
        while i < n and s[i].isspace():
            i += 1

        if i >= n:
            break

        token_parts = []

        while i < n:
            c = s[i]

            # Whitespace ends the token
            if c.isspace():
                break

            # Single quote: everything inside is literal, no escapes
            if c == "'":
                i += 1
                while i < n and s[i] != "'":
                    token_parts.append(s[i])
                    i += 1
                if i < n and s[i] == "'":
                    i += 1  # consume closing single quote
                # If we reach end without closing quote, it's an error in real shlex,
                # but we just handle it gracefully by ending the token.
                continue

            # Double quote: backslash escapes only backslash or double quote inside
            if c == '"':
                i += 1
                while i < n and s[i] != '"':
                    if s[i] == '\\':
                        # Look at next character
                        if i + 1 < n and s[i + 1] in ('\\', '"'):
                            token_parts.append(s[i + 1])
                            i += 2
                        else:
                            # Backslash is literal
                            token_parts.append('\\')
                            i += 1
                    else:
                        token_parts.append(s[i])
                        i += 1
                if i < n and s[i] == '"':
                    i += 1  # consume closing double quote
                continue

            # Backslash outside quotes: escapes the next character
            if c == '\\':
                if i + 1 < n:
                    token_parts.append(s[i + 1])
                    i += 2
                else:
                    # Backslash at end: treat as literal backslash
                    token_parts.append('\\')
                    i += 1
                continue

            # Regular character
            token_parts.append(c)
            i += 1

        tokens.append(''.join(token_parts))

    return tokens
