def shlex_split(s):
    """Reproduce shlex.split(s) in POSIX mode from scratch."""
    tokens = []
    current_token = []
    in_single_quote = False
    in_double_quote = False
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if in_single_quote:
            if c == "'":
                in_single_quote = False
                i += 1
            else:
                current_token.append(c)
                i += 1
        elif in_double_quote:
            if c == '"':
                in_double_quote = False
                i += 1
            elif c == '\\' and i + 1 < n:
                next_c = s[i + 1]
                if next_c == '"' or next_c == '\\':
                    current_token.append(next_c)
                    i += 2
                else:
                    current_token.append('\\')
                    i += 1
            else:
                current_token.append(c)
                i += 1
        else:
            if c == "'":
                in_single_quote = True
                i += 1
            elif c == '"':
                in_double_quote = True
                i += 1
            elif c == '\\' and i + 1 < n:
                current_token.append(s[i + 1])
                i += 2
            elif c in (' ', '\t', '\n', '\r', '\f'):
                if current_token:
                    tokens.append(''.join(current_token))
                    current_token = []
                i += 1
            else:
                current_token.append(c)
                i += 1

    if current_token:
        tokens.append(''.join(current_token))

    return tokens
